/* Guardian FiveM Operations + Discord Tickets add-on */
(()=>{
 const E=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
 const req=async(url,opt={})=>{const r=await fetch(url,{credentials:"same-origin",cache:"no-store",headers:{"Content-Type":"application/json",...(opt.headers||{})},...opt});const d=await r.json().catch(()=>({}));if(!r.ok||d.ok===false)throw new Error(d.error||`Request failed (${r.status})`);return d};
 const note=(msg,bad=false)=>{const n=document.createElement("div");n.className="gctlNotice"+(bad?" bad":"");n.textContent=msg;document.body.appendChild(n);setTimeout(()=>n.remove(),4000)};
 const dt=v=>v?new Date(v).toLocaleString():"Never";
 const dur=v=>{v=Math.max(0,Number(v)||0);const d=Math.floor(v/86400),h=Math.floor(v%86400/3600),m=Math.floor(v%3600/60);return d?`${d}d ${h}h ${m}m`:`${h}h ${m}m`};
 const statusBadge=(ok,text)=>`<span class="gctlBadge ${ok?'good':'bad'}">${E(text)}</span>`;
 window.renderGuardianFiveM=async function(){
  const c=document.getElementById("content");c.innerHTML='<div class="card"><h3>Loading FiveM Operations…</h3></div>';
  try{
   const d=await req("/api/admin/fivem/monitor"),m=d.metrics||{},players=Array.isArray(d.players)?d.players:[],resources=Array.isArray(d.resources)?d.resources:[];
   c.innerHTML=`<div class="gctlWrap">
    <div class="gctlHeader"><div><div class="eyebrow">GUARDIAN OPERATIONS</div><h2>FiveM Control Centre</h2><p>Live monitoring and authorised server actions.</p></div><div>${statusBadge(d.connected,d.connected?"BRIDGE CONNECTED":"BRIDGE OFFLINE")} <button id="gctlRefresh">Refresh</button></div></div>
    <div class="gctlStats">
     <div class="card"><small>SERVER STATUS</small><strong>${d.connected?"ONLINE":"OFFLINE"}</strong><span>Heartbeat: ${E(dt(d.lastHeartbeat))}</span></div>
     <div class="card"><small>PLAYERS</small><strong>${Number(m.playerCount??players.length)} / ${Number(m.maxPlayers||0)||"—"}</strong><span>Live connected players</span></div>
     <div class="card"><small>SERVER UPTIME</small><strong>${m.uptimeSeconds!=null?E(dur(m.uptimeSeconds)):"—"}</strong><span>Since resource/server start</span></div>
     <div class="card"><small>RESOURCES</small><strong>${resources.length}</strong><span>${resources.filter(r=>r.state==="started").length} started</span></div>
    </div>
    <div class="gctlCols">
     <section class="card"><div class="gctlSection"><div><h3>Live Players</h3><p>Kick actions require a reason and are recorded in the audit log.</p></div><input id="gctlPlayerSearch" placeholder="Search players…"></div>
      <div class="gctlTableWrap"><table class="gctlTable"><thead><tr><th>ID</th><th>Player</th><th>Ping</th><th>Action</th></tr></thead><tbody id="gctlPlayers">${players.map(p=>`<tr data-player="${E((p.name||"")+" "+p.serverId)}"><td>${E(p.serverId)}</td><td>${E(p.name)}</td><td>${E(p.ping)} ms</td><td><button class="danger" data-kick="${E(p.serverId)}">Kick</button></td></tr>`).join("")||'<tr><td colspan="4" class="muted">No live player data. Check that the Guardian FiveM resource is installed and running.</td></tr>'}</tbody></table></div>
     </section>
     <section class="card"><div class="gctlSection"><div><h3>Resource Management</h3><p>Critical resources are protected by the FiveM bridge.</p></div><input id="gctlResourceSearch" placeholder="Search resources…"></div>
      <div class="gctlTableWrap"><table class="gctlTable"><thead><tr><th>Resource</th><th>Status</th><th>Actions</th></tr></thead><tbody id="gctlResources">${resources.map(r=>`<tr data-resource="${E(r.name)}"><td>${E(r.name)}</td><td>${statusBadge(r.state==="started",r.state||"unknown")}</td><td><div class="gctlButtons"><button data-resource-action="startResource" data-resource="${E(r.name)}">Start</button><button data-resource-action="restartResource" data-resource="${E(r.name)}">Restart</button><button class="danger" data-resource-action="stopResource" data-resource="${E(r.name)}">Stop</button></div></td></tr>`).join("")||'<tr><td colspan="3" class="muted">No resource telemetry received.</td></tr>'}</tbody></table></div>
     </section>
    </div>
    <section class="card"><div class="gctlSection"><div><h3>Restart Management</h3><p>Use txAdmin for actual server restart scheduling. Guardian can display a schedule and notify Discord, but a server restart must be explicitly connected to a supported txAdmin control.</p></div></div>
     <div class="gctlRestart"><label>Next scheduled restart (local time)<input id="gctlRestartAt" type="datetime-local"></label><label>Announcement channel ID (optional)<input id="gctlRestartChannel" placeholder="Discord channel ID"></label><button id="gctlSaveRestart">Save schedule</button><button id="gctlNotifyRestart">Send test announcement</button></div><p id="gctlRestartInfo" class="muted">Schedule is stored in Guardian. Configure the actual restart in txAdmin unless your host provides a supported restart API.</p>
    </section>
   </div>`;
   const saved=await req("/api/admin/fivem/restart-schedule").catch(()=>({schedule:{}}));if(saved.schedule?.at)document.getElementById("gctlRestartAt").value=saved.schedule.at; if(saved.schedule?.channelId)document.getElementById("gctlRestartChannel").value=saved.schedule.channelId;
   document.getElementById("gctlRefresh").onclick=()=>window.renderGuardianFiveM();
   document.getElementById("gctlPlayerSearch").oninput=e=>document.querySelectorAll("#gctlPlayers tr[data-player]").forEach(r=>r.hidden=!r.dataset.player.toLowerCase().includes(e.target.value.toLowerCase()));
   document.getElementById("gctlResourceSearch").oninput=e=>document.querySelectorAll("#gctlResources tr[data-resource]").forEach(r=>r.hidden=!r.dataset.resource.toLowerCase().includes(e.target.value.toLowerCase()));
   document.querySelectorAll("[data-kick]").forEach(b=>b.onclick=async()=>{const reason=prompt(`Reason for kicking player ${b.dataset.kick}:`);if(!reason?.trim())return; if(!confirm(`Kick player ${b.dataset.kick}?`))return;try{await req("/api/admin/fivem/action",{method:"POST",body:JSON.stringify({operation:"kickPlayer",data:{serverId:Number(b.dataset.kick),reason}})});note("Kick command sent to FiveM bridge.");}catch(e){note(e.message,true)}});
   document.querySelectorAll("[data-resource-action]").forEach(b=>b.onclick=async()=>{const op=b.dataset.resourceAction,name=b.dataset.resource;if(!confirm(`${op.replace("Resource","")} resource "${name}"?`))return;try{await req("/api/admin/fivem/action",{method:"POST",body:JSON.stringify({operation:op,data:{resource:name}})});note("Resource command sent. Refresh to verify status.");}catch(e){note(e.message,true)}});
   document.getElementById("gctlSaveRestart").onclick=async()=>{try{const at=document.getElementById("gctlRestartAt").value,channelId=document.getElementById("gctlRestartChannel").value.trim();await req("/api/admin/fivem/restart-schedule",{method:"POST",body:JSON.stringify({at,channelId})});note("Restart schedule saved in Guardian.");}catch(e){note(e.message,true)}};
   document.getElementById("gctlNotifyRestart").onclick=async()=>{try{await req("/api/admin/fivem/restart-schedule/announce",{method:"POST",body:JSON.stringify({channelId:document.getElementById("gctlRestartChannel").value.trim(),message:"Guardian test: server restart announcement integration check."})});note("Test announcement sent.");}catch(e){note(e.message,true)}};
  }catch(e){c.innerHTML=`<div class="card"><h3>FiveM Control Centre unavailable</h3><p>${E(e.message)}</p><button onclick="renderGuardianFiveM()">Retry</button></div>`}
 };
 let guardianTicketAvailableRoles=[];
 let guardianTicketRolesLoaded=false;
 const ticketCategoryRow=cat=>{
  const savedRoleIds=Array.isArray(cat?.accessRoleIds)?cat.accessRoleIds.map(String):[];
  const selected=new Set(savedRoleIds);
  const roleOptions=guardianTicketRolesLoaded
   ?(guardianTicketAvailableRoles.map(role=>`<label class="gctlTicketRoleOption"><input type="checkbox" data-cat-role value="${E(role.id)}" ${selected.has(String(role.id))?"checked":""}><span class="gctlTicketRoleDot" style="--ticket-role-colour:${E(role.color||"#687078")}"></span><span>${E(role.name)}</span></label>`).join("")||'<small class="muted">No selectable roles found in this Discord server.</small>')
   :`<small class="muted">${savedRoleIds.length?`Saved role IDs: ${E(savedRoleIds.join(", "))}. `:""}Click “Load Discord Roles” to choose one or more roles.</small>`;
  return `<div class="gctlCategoryEditorRow" data-cat-saved-role-ids="${E(savedRoleIds.join(","))}">
   <div class="gctlCategoryFields">
    <label>Category name<input data-cat-label value="${E(cat?.label||"")}" maxlength="80" placeholder="e.g. Whitelist Application"></label>
    <label>Button ID<input data-cat-key value="${E(cat?.key||"")}" maxlength="40" placeholder="auto-generated-from-name"></label>
    <label>Button colour<select data-cat-style><option value="Primary" ${cat?.style==="Primary"?"selected":""}>Blue</option><option value="Secondary" ${!cat?.style||cat?.style==="Secondary"?"selected":""}>Grey</option><option value="Success" ${cat?.style==="Success"?"selected":""}>Green</option><option value="Danger" ${cat?.style==="Danger"?"selected":""}>Red</option></select></label>
    <label>Default priority<select data-cat-priority><option value="normal" ${cat?.priority!=="high"?"selected":""}>Normal</option><option value="high" ${cat?.priority==="high"?"selected":""}>High</option></select></label>
    <button type="button" class="danger gctlRemoveCategory">Remove</button>
   </div>
   <div class="gctlCategoryRoleAccess"><div class="gctlRoleAccessHeading"><strong>Roles allowed to access these tickets</strong><small>Selected roles can view and reply in the private ticket, and use the close button. Global ticket staff roles still have access to every ticket. This does not restrict who can see the public panel.</small></div><div class="gctlTicketRoleOptions" data-cat-roles>${roleOptions}</div></div>
  </div>`;
 };
 window.renderGuardianTickets=async function(){
  const c=document.getElementById("content");c.innerHTML='<div class="card"><h3>Loading Discord Tickets…</h3></div>';
  try{
   const d=await req("/api/admin/tickets"),tickets=d.tickets||[],categories=Array.isArray(d.categories)?d.categories:[];
   const categoryByKey=new Map(categories.map(x=>[String(x.key),x]));
   const loggedCategoryKeys=[...new Set([...categories.map(x=>String(x.key||"")),...tickets.map(t=>String(t.category||""))].filter(Boolean))];
   const loggedCategories=loggedCategoryKeys.map(key=>({key,label:categoryByKey.get(key)?.label||tickets.find(t=>String(t.category||"")===key)?.categoryLabel||tickets.find(t=>String(t.category||"")===key)?.title||key}));
   c.innerHTML=`<div class="gctlWrap"><div class="gctlHeader"><div><div class="eyebrow">COMMUNITY SUPPORT</div><h2>Discord Tickets</h2><p>Tickets opened in Discord are shared with this dashboard. Closed tickets are archived here with their transcript after the Discord channel is deleted.</p></div>${statusBadge(d.discordConnected,"Discord "+(d.discordConnected?"connected":"disconnected"))}</div>
   <div class="gctlTicketSetup card"><div><h3>Publish ticket panel</h3><p>Enter the Discord text channel where members will see the ticket buttons.</p></div><div class="gctlInline"><input id="gctlPanelChannel" value="${E(d.panel?.channelId||"")}" placeholder="Discord channel ID"><button type="button" id="gctlLoadRoles">Load Discord Roles</button><button id="gctlPostPanel">Post / Update Panel</button></div><small id="gctlRoleLoadStatus" class="muted">Load roles from the Discord server, choose the roles allowed into each private ticket, then save categories and publish the panel. The panel stays public; these roles control access after a ticket is opened.</small></div>
   <section class="card gctlCategoryManager"><div class="gctlSection"><div><h3>Ticket Categories</h3><p>Add, rename, recolour, set default priority, and choose which Discord roles can access tickets from each button.</p></div><span class="gctlBadge">${categories.length} / 25 categories</span></div>
    <div id="gctlCategoryList" class="gctlCategoryList">${categories.map(ticketCategoryRow).join("")}</div>
    <div class="gctlCategoryActions"><button type="button" id="gctlAddCategory">+ Add category</button><button type="button" id="gctlSaveCategories">Save categories</button></div>
    <small class="muted">Save categories before testing. Role access applies to newly created tickets; changing the category does not change permissions on existing ticket channels. Global ticket staff roles remain able to access every ticket. Reposting updates the visible Discord buttons when possible.</small>
   </section>
   <div class="gctlTicketFilters"><input id="gctlTicketSearch" placeholder="Search ticket number, player name or ID…" /><select id="gctlTicketCategory"><option value="">All categories</option>${loggedCategories.map(x=>`<option value="${E(x.key)}">${E(x.label)}</option>`).join("")}</select><select id="gctlTicketSource"><option value="">All sources</option><option value="discord">Discord</option><option value="fivem">FiveM / In-game</option><option value="website">Website</option></select><select id="gctlTicketStatus"><option value="">All statuses</option><option value="open">Open</option><option value="in_progress">In progress</option><option value="waiting">Waiting</option><option value="closed">Closed / Archived</option></select><button id="gctlTicketRefresh">Refresh</button></div>
   <div class="gctlTicketLayout"><section class="card"><div class="gctlTableWrap"><table class="gctlTable"><thead><tr><th>Ticket</th><th>Player / Creator</th><th>Category</th><th>Source</th><th>Status</th><th>Assigned</th></tr></thead><tbody id="gctlTicketRows">${tickets.map(t=>{const cat=categoryByKey.get(String(t.category||""));const categoryLabel=t.categoryLabel||cat?.label||t.title||t.category||"Uncategorised";const source=t.source||"discord";return `<tr class="gctlTicketRow" data-id="${E(t.id)}" data-search="${E(`${t.number} ${t.title} ${categoryLabel} ${t.createdByName||""} ${t.createdByDiscordId||""} ${source}`.toLowerCase())}" data-status="${E(t.status)}" data-category="${E(t.category||"")}" data-source="${E(source)}"><td><b>${E(t.number)}</b>${t.channelDeleted?'<br><small class="gctlArchivedLabel">Archived transcript</small>':''}</td><td>${E(t.createdByName||"Unknown")}<br><small>${E(t.createdByType||"player")} · ${E(t.createdByDiscordId||"no Discord ID")}</small></td><td>${E(categoryLabel)}</td><td>${E(source==="fivem"?"FiveM / In-game":source.charAt(0).toUpperCase()+source.slice(1))}</td><td>${E(t.status)}${t.channelDeleted?" · archived":""}</td><td>${E(t.assignedTo||"Unassigned")}</td></tr>`}).join("")||'<tr><td colspan="6" class="muted">No tickets yet. Post the Discord panel to get started.</td></tr>'}</tbody></table></div></section><section class="card" id="gctlTicketDetail"><div class="gctlEmpty">Select a ticket to view its conversation.</div></section></div></div>`;
   const readTicketCategoryRows=()=>[...document.querySelectorAll("#gctlCategoryList .gctlCategoryEditorRow")].map(row=>({
    label:row.querySelector("[data-cat-label]").value.trim(),
    key:row.querySelector("[data-cat-key]").value.trim(),
    style:row.querySelector("[data-cat-style]").value,
    priority:row.querySelector("[data-cat-priority]").value,
    accessRoleIds:guardianTicketRolesLoaded?[...row.querySelectorAll("[data-cat-role]:checked")].map(el=>el.value):String(row.dataset.catSavedRoleIds||"").split(",").map(x=>x.trim()).filter(Boolean)
   }));
   const loadTicketRoles=async(quiet=false)=>{
    const status=document.getElementById("gctlRoleLoadStatus");
    const button=document.getElementById("gctlLoadRoles");
    const previousRows=readTicketCategoryRows();
    const channelId=document.getElementById("gctlPanelChannel").value.trim();
    if(button)button.disabled=true;
    if(status)status.textContent="Loading roles from Discord…";
    try{
     const endpoint="/api/admin/tickets/roles"+(channelId?`?channelId=${encodeURIComponent(channelId)}`:"");
     const data=await req(endpoint);
     guardianTicketAvailableRoles=Array.isArray(data.roles)?data.roles:[];
     guardianTicketRolesLoaded=true;
     const list=document.getElementById("gctlCategoryList");
     if(list)list.innerHTML=previousRows.map(ticketCategoryRow).join("");
     if(status)status.textContent=`Loaded ${guardianTicketAvailableRoles.length} roles from ${data.guild?.name||"your Discord server"}. Select one or more roles under each category, then click Save categories.`;
     if(!quiet)note(`Loaded ${guardianTicketAvailableRoles.length} Discord roles.`);
    }catch(e){
     if(status)status.textContent="Could not load Discord roles: "+e.message;
     if(!quiet)note(e.message,true);
    }finally{if(button)button.disabled=false;}
   };
   document.getElementById("gctlLoadRoles").onclick=()=>loadTicketRoles(false);
   document.getElementById("gctlPostPanel").onclick=async()=>{const channelId=document.getElementById("gctlPanelChannel").value.trim();if(!channelId)return note("Enter a Discord channel ID.",true);try{const result=await req("/api/admin/tickets/panel",{method:"POST",body:JSON.stringify({channelId})});note(result.updated?"Discord ticket panel updated.":"Discord ticket panel posted.");}catch(e){note(e.message,true)}};
   document.getElementById("gctlAddCategory").onclick=()=>{const list=document.getElementById("gctlCategoryList");if(list.querySelectorAll(".gctlCategoryEditorRow").length>=25)return note("Discord supports up to 25 categories in this panel.",true);list.insertAdjacentHTML("beforeend",ticketCategoryRow({label:"",key:"",style:"Secondary",priority:"normal",accessRoleIds:[]}));};
   document.getElementById("gctlCategoryList").onclick=e=>{const b=e.target.closest(".gctlRemoveCategory");if(b)b.closest(".gctlCategoryEditorRow")?.remove()};
   document.getElementById("gctlSaveCategories").onclick=async()=>{const categoryRows=readTicketCategoryRows();try{const result=await req("/api/admin/tickets/categories",{method:"POST",body:JSON.stringify({categories:categoryRows})});if(result.panelUpdated)note("Categories and role access saved; Discord panel updated.");else if(result.panelWarning)note("Categories saved, but panel update failed: "+result.panelWarning,true);else note("Categories and role access saved. Post / Update Panel to publish the buttons.");await window.renderGuardianTickets();}catch(e){note(e.message,true)}};
   if(!guardianTicketRolesLoaded)setTimeout(()=>loadTicketRoles(true),0);
   document.getElementById("gctlTicketRefresh").onclick=()=>window.renderGuardianTickets();
   const filter=()=>{const q=document.getElementById("gctlTicketSearch").value.toLowerCase(),st=document.getElementById("gctlTicketStatus").value,cat=document.getElementById("gctlTicketCategory").value,src=document.getElementById("gctlTicketSource").value;document.querySelectorAll(".gctlTicketRow").forEach(r=>r.hidden=!(r.dataset.search.includes(q)&&(!st||r.dataset.status===st)&&(!cat||r.dataset.category===cat)&&(!src||r.dataset.source===src)))};
   document.getElementById("gctlTicketSearch").oninput=filter;document.getElementById("gctlTicketStatus").onchange=filter;document.getElementById("gctlTicketCategory").onchange=filter;document.getElementById("gctlTicketSource").onchange=filter;
   document.querySelectorAll(".gctlTicketRow").forEach(r=>r.onclick=()=>showTicket(r.dataset.id));
   async function showTicket(id){
    const t=(await req("/api/admin/tickets")).tickets.find(x=>x.id===id);if(!t)return;
    const box=document.getElementById("gctlTicketDetail");
    const categoryInfo=categories.find(x=>x.key===t.category);
    const categoryLabel=t.categoryLabel||categoryInfo?.label||t.title||t.category||"Uncategorised";
    const sourceLabel=(t.source||"discord")==="fivem"?"FiveM / In-game":(t.source||"discord").charAt(0).toUpperCase()+(t.source||"discord").slice(1);
    const statusControl=t.status==="closed"?`<select id="gctlStatus" disabled><option value="closed" selected>Closed / archived</option></select>`:`<select id="gctlStatus">${["open","in_progress","waiting","closed"].map(x=>`<option value="${x}" ${x===t.status?"selected":""}>${x.replace("_"," ")}</option>`).join("")}</select>`;
    box.innerHTML=`<div class="gctlTicketDetailHead"><div><div class="eyebrow">${E(t.number)} · ${E(categoryLabel)}</div><h3>${E(t.title||categoryLabel)}</h3><p>Created by <strong>${E(t.createdByName||"Unknown player")}</strong> (${E(t.createdByType||"player")}) · ${E(sourceLabel)} · ${E(dt(t.createdAt))}</p><p>Discord user ID: ${E(t.createdByDiscordId||"Not available")} · Priority: ${E(String(t.priority||"normal").toUpperCase())}</p>${t.respondingTeam?`<p>Responding team: ${E(t.respondingTeam)}</p>`:""}</div>${statusControl}</div>
    <div class="gctlAssign"><label>Assigned staff<input id="gctlAssigned" value="${E(t.assignedTo||"")}" placeholder="Staff username" ${t.status==="closed"?"disabled":""}></label><button id="gctlAssignBtn" ${t.status==="closed"?"disabled":""}>Save assignment</button></div>
    ${t.channelDeleted?`<div class="gctlArchiveNotice"><strong>Archived ticket record</strong><span>${t.transcriptCaptureComplete?"The Discord channel was deleted after Guardian captured its message history. The transcript is retained below.":"The Discord channel was already missing, so Guardian could not download its full history. Only messages previously saved to Guardian are available below."}</span><small>Closed by ${E(t.closedBy||t.channelDeletedBy||"Unknown")} · ${E(dt(t.closedAt||t.channelDeletedAt))}${t.transcriptCaptureComplete?` · ${Number(t.transcriptMessageCount||0)} Discord messages captured`:""}</small></div>`:""}
    <div class="gctlMessages">${(t.messages||[]).map(m=>`<article class="gctlMessage ${m.source==="website"?"staff":""}"><header>${E(m.authorName||"Unknown")} · ${E(m.source||"discord")} · ${E(dt(m.createdAt))}</header><p>${E(m.content||"(attachment)")}</p>${(m.attachments||[]).map(a=>`<a href="${E(a.url)}" target="_blank" rel="noopener noreferrer">${E(a.name||"Attachment")}</a>`).join(" ")}</article>`).join("")||'<p class="muted">No messages recorded in this ticket yet.</p>'}</div>
    ${t.status==="closed"?`${t.channelDeleted?'<p class="muted">This ticket is closed and archived. Reopening is unavailable because its Discord channel has been deleted.</p>':'<div class="gctlArchiveNotice"><strong>Closure not yet completed</strong><span>The ticket is marked closed but the Discord channel still exists. Retry archive and deletion once the bot has permission to read history and manage channels.</span><button type="button" id="gctlRetryDelete">Retry archive &amp; delete Discord channel</button></div>'}`:'<form id="gctlReplyForm"><textarea id="gctlReply" maxlength="4000" placeholder="Reply to the ticket…"></textarea><button>Send reply</button></form>'}`;
    const statusSelect=box.querySelector("#gctlStatus");if(statusSelect)statusSelect.onchange=async e=>{const newStatus=e.target.value;try{const result=await req(`/api/admin/tickets/${id}/status`,{method:"POST",body:JSON.stringify({status:newStatus})});if(newStatus==="closed"&&result.channelDeleted)note("Ticket closed. Discord channel deleted and transcript saved in Guardian.");else if(newStatus==="closed")note("Ticket closed, but the Discord channel was not deleted. Check the warning and retry.",true);else if(!result.channelUpdated)note("Status saved, but Discord update failed: "+(result.channelWarning||"unknown error"),true);else note("Ticket status updated.");await window.renderGuardianTickets();}catch(err){note(err.message,true);await showTicket(id)}};
    const retryDelete=box.querySelector("#gctlRetryDelete");if(retryDelete)retryDelete.onclick=async()=>{retryDelete.disabled=true;try{const result=await req(`/api/admin/tickets/${id}/status`,{method:"POST",body:JSON.stringify({status:"closed"})});if(result.channelDeleted)note("Discord channel deleted; website transcript preserved.");else note("Channel deletion did not complete.",true);await window.renderGuardianTickets();}catch(err){note(err.message,true);await showTicket(id)}finally{retryDelete.disabled=false}};
    box.querySelector("#gctlAssignBtn").onclick=async()=>{try{await req(`/api/admin/tickets/${id}/assign`,{method:"POST",body:JSON.stringify({assignedTo:box.querySelector("#gctlAssigned").value})});note("Ticket assigned.");}catch(e){note(e.message,true)}};
    const form=box.querySelector("#gctlReplyForm");if(form)form.onsubmit=async e=>{e.preventDefault();const input=box.querySelector("#gctlReply"),content=input.value.trim();if(!content)return;try{await req(`/api/admin/tickets/${id}/messages`,{method:"POST",body:JSON.stringify({content})});note("Reply sent.");await showTicket(id)}catch(err){note(err.message,true)}};
   }
  }catch(e){c.innerHTML=`<div class="card"><h3>Ticket system unavailable</h3><p>${E(e.message)}</p><button onclick="renderGuardianTickets()">Retry</button></div>`}
 };


 // ============================================================
 // Backup & recovery tools
 // ============================================================
 const prettyBytes=v=>{v=Math.max(0,Number(v)||0);if(v<1024)return `${v} B`;if(v<1024*1024)return `${(v/1024).toFixed(1)} KB`;if(v<1024*1024*1024)return `${(v/1024/1024).toFixed(2)} MB`;return `${(v/1024/1024/1024).toFixed(2)} GB`};
 window.renderGuardianBackups=async function(){
  const c=document.getElementById('content');c.innerHTML='<div class="card"><h3>Loading backup & recovery tools…</h3></div>';
  try{
   const [d,snap]=await Promise.all([req('/api/admin/recovery'),req('/api/admin/snapshots')]);
   const st=d.settings||{},backups=d.backups||[],snaps=snap.snapshots||[],successful=backups.filter(x=>x.status==='success'&&x.retained),failed=backups.filter(x=>x.status==='failed');
   c.innerHTML=`<div class="gctlWrap gctlBackupWrap">
    <div class="gctlHeader"><div><div class="eyebrow">GUARDIAN SYSTEM RECOVERY</div><h2>Backups & Restore Points</h2><p>Scheduled full data backups, named configuration restore points, and recovery history.</p></div><div>${statusBadge(!!st.enabled,st.enabled?'SCHEDULED BACKUPS ON':'SCHEDULED BACKUPS OFF')} <button id="gbrRefresh">Refresh</button></div></div>
    <div class="gctlStats gctlBackupStats">
     <div class="card"><small>RETAINED BACKUPS</small><strong>${successful.length}</strong><span>Full data backups available</span></div>
     <div class="card"><small>LAST BACKUP</small><strong>${E(st.lastRunAt?new Date(st.lastRunAt).toLocaleDateString():'—')}</strong><span>${E(st.lastRunAt?new Date(st.lastRunAt).toLocaleTimeString():'No run recorded')}</span></div>
     <div class="card"><small>NEXT SCHEDULED RUN</small><strong>${E(st.enabled&&st.nextRunAt?new Date(st.nextRunAt).toLocaleDateString():'—')}</strong><span>${E(st.enabled&&st.nextRunAt?new Date(st.nextRunAt).toLocaleTimeString():st.enabled?'Schedule pending':'Scheduling disabled')}</span></div>
     <div class="card"><small>FAILED RUNS</small><strong>${failed.length}</strong><span>Recent runs shown below</span></div>
    </div>
    <div class="gctlBackupColumns">
     <section class="card"><div class="gctlSection"><div><h3>Scheduled backups</h3><p>Back up the Guardian data directory automatically while this web service is running.</p></div></div>
      <div class="gctlFormGrid"><label class="gctlToggleLine"><input id="gbrEnabled" type="checkbox" ${st.enabled?'checked':''}> Enable scheduled backups</label>
       <label>Run every<select id="gbrInterval">${[[6,'Every 6 hours'],[12,'Every 12 hours'],[24,'Every 24 hours'],[48,'Every 48 hours'],[168,'Every 7 days']].map(([n,l])=>`<option value="${n}" ${Number(st.intervalHours||24)===n?'selected':''}>${l}</option>`).join('')}</select></label>
       <label>Keep successful backups<select id="gbrRetention">${[3,7,14,30,45,60].map(n=>`<option value="${n}" ${Number(st.retentionCount||14)===n?'selected':''}>${n} backups</option>`).join('')}</select></label>
       <label class="gctlFullWidth">Discord alert channel ID<input id="gbrAlertChannel" value="${E(st.alertChannelId||'')}" placeholder="Channel ID for backup failure alerts"></label>
      </div><p class="muted">Failure alerts are sent to the selected channel if the Discord bot is connected. Failures are also recorded in Guardian and Render logs.</p>
      <div class="gctlButtons"><button id="gbrSaveSettings">Save schedule</button><button id="gbrRunNow">Create backup now</button></div>
     </section>
     <section class="card"><div class="gctlSection"><div><h3>Storage & recovery notes</h3><p>Full backups contain files under <code>data/</code> except the backup directory and backup run history.</p></div></div>
      <div class="gctlRecoveryNote"><strong>Persistent storage required</strong><p>On Render, files in the service filesystem may be lost when an instance is replaced unless your service uses a persistent disk. Keep an off-site copy of important backups.</p></div>
      <div class="gctlRecoveryNote"><strong>Restore behaviour</strong><p>Restoring a full backup creates an automatic pre-restore backup, validates checksums, replaces the data files, and requires a web-service restart to reload the in-memory records.</p></div>
      <div class="gctlRecoveryNote"><strong>Security</strong><p>Backup files can contain member records, tickets, staff data and configuration. Restrict access and store downloaded backups securely.</p></div>
     </section>
    </div>
    <section class="card"><div class="gctlSection"><div><h3>Full data backup history</h3><p>Download an archive or restore the app's data files from a retained backup.</p></div><span class="gctlBadge">${backups.length} recent runs</span></div>
     <div class="gctlTableWrap"><table class="gctlTable gctlRecoveryTable"><thead><tr><th>Created</th><th>Type</th><th>Status</th><th>Files</th><th>Archive size</th><th>Created by / details</th><th>Actions</th></tr></thead><tbody>${backups.map(b=>`<tr><td>${E(dt(b.createdAt))}</td><td>${E(b.kind||'manual')}</td><td>${statusBadge(b.status==='success',String(b.status||'unknown').toUpperCase())}</td><td>${Number(b.fileCount||0)}</td><td>${E(prettyBytes(b.sizeBytes))}</td><td><span>${E(b.createdBy||'SYSTEM')}</span>${b.error?`<small class="gctlErrorText">${E(b.error)}</small>`:''}</td><td><div class="gctlButtons">${b.retained?`<button data-gbr-download="${E(b.id)}">Download</button><button class="danger" data-gbr-restore="${E(b.id)}">Restore</button>`:'<span class="muted">Not retained</span>'}</div></td></tr>`).join('')||'<tr><td colspan="7" class="muted">No backup runs yet. Use Create backup now or enable a schedule.</td></tr>'}</tbody></table></div>
    </section>
    <section class="card"><div class="gctlSection"><div><h3>Configuration restore points</h3><p>Quick snapshots of Guardian configuration and selected operational settings before major changes.</p></div></div>
     <div class="gctlInline gctlSnapshotCreate"><input id="gbrSnapshotName" placeholder="Restore point name, e.g. Before settings change"><button id="gbrCreateSnapshot">Create restore point</button></div>
     <div class="gctlSnapshotList">${snaps.map(x=>`<div class="gctlSnapshotRow"><div><strong>${E(x.name||'Restore point')}</strong><small>${E(dt(x.createdAt))} · ${E(x.createdBy||'SYSTEM')}</small></div><button data-gbr-snapshot-restore="${E(x.id)}" class="danger">Restore point</button></div>`).join('')||'<p class="muted">No configuration snapshots yet.</p>'}</div>
    </section>
    <section class="card"><div class="gctlSection"><div><h3>Restore from an off-site full backup</h3><p>Upload a previously downloaded Guardian <code>.json.gz</code> full-data archive. Guardian validates it and creates a pre-restore backup first.</p></div></div>
     <div class="gctlInline gctlSnapshotCreate"><input id="gbrFullRestoreFile" type="file" accept=".gz,.json.gz,application/gzip"><button class="danger" id="gbrRestoreUploaded">Upload &amp; restore full backup</button></div><p class="muted">This replaces data files in the current Guardian data directory. After a successful restore, restart the web service in Render.</p>
    </section>
    <section class="card"><div class="gctlSection"><div><h3>Portable configuration export</h3><p>Download or import the existing JSON configuration backup. This is a configuration export, not a full data archive.</p></div></div>
     <div class="gctlButtons"><button id="gbrExportConfig">Download configuration JSON</button><input id="gbrImportFile" type="file" accept=".json,application/json"></div><textarea id="gbrImportData" rows="5" placeholder="Optional: paste a configuration backup JSON here"></textarea><button class="danger" id="gbrImportConfig">Restore configuration JSON</button>
    </section>
   </div>`;
   $('gbrRefresh').onclick=()=>window.renderGuardianBackups();
   $('gbrSaveSettings').onclick=async()=>{try{const r=await req('/api/admin/recovery/settings',{method:'POST',body:JSON.stringify({enabled:$('gbrEnabled').checked,intervalHours:Number($('gbrInterval').value),retentionCount:Number($('gbrRetention').value),alertChannelId:$('gbrAlertChannel').value.trim()})});note('Backup schedule saved.');await window.renderGuardianBackups()}catch(e){note(e.message,true)}};
   $('gbrRunNow').onclick=async e=>{const b=e.currentTarget;b.disabled=true;b.textContent='Creating backup…';try{const r=await req('/api/admin/recovery/backups',{method:'POST',body:'{}'});note(`Backup created: ${r.backup.fileCount} files, ${prettyBytes(r.backup.sizeBytes)} archive.`);await window.renderGuardianBackups()}catch(err){note(err.message,true)}finally{b.disabled=false;b.textContent='Create backup now'}};
   document.querySelectorAll('[data-gbr-download]').forEach(b=>b.onclick=()=>{location.href='/api/admin/recovery/backups/'+encodeURIComponent(b.dataset.gbrDownload)+'/download'});
   document.querySelectorAll('[data-gbr-restore]').forEach(b=>b.onclick=async()=>{if(!confirm('Restore this full data backup? Guardian first creates a pre-restore backup. The current data files will be replaced, and the web service must be restarted afterwards.'))return;if(!confirm('Last check: restore data from '+b.dataset.gbrRestore+' now?'))return;b.disabled=true;try{const r=await req('/api/admin/recovery/backups/'+encodeURIComponent(b.dataset.gbrRestore)+'/restore',{method:'POST',body:'{}'});alert(`Restore completed. ${r.filesRestored} data files restored.\n\nRestart the Guardian web service in Render now so all in-memory records reload.\nPre-restore backup: ${r.preRestoreBackupId}`);await window.renderGuardianBackups()}catch(e){note(e.message,true)}finally{b.disabled=false}});
   $('gbrCreateSnapshot').onclick=async()=>{try{await req('/api/admin/snapshots',{method:'POST',body:JSON.stringify({name:$('gbrSnapshotName').value.trim()||'Manual restore point'})});note('Configuration restore point created.');await window.renderGuardianBackups()}catch(e){note(e.message,true)}};
   document.querySelectorAll('[data-gbr-snapshot-restore]').forEach(b=>b.onclick=async()=>{if(!confirm('Restore this configuration snapshot? Current settings will be replaced.'))return;try{await req('/api/admin/snapshots/'+encodeURIComponent(b.dataset.gbrSnapshotRestore)+'/restore',{method:'POST',body:'{}'});alert('Configuration snapshot restored. Some changes may require a page refresh.');await window.renderGuardianBackups()}catch(e){note(e.message,true)}});
   $('gbrRestoreUploaded').onclick=async e=>{const file=$('gbrFullRestoreFile').files?.[0];if(!file)return note('Choose a downloaded Guardian .json.gz full backup first.',true);if(file.size>220*1024*1024)return note('The upload exceeds the 220 MB limit.',true);if(!confirm(`Restore full Guardian data from ${file.name}? A pre-restore backup will be created first. You will need to restart the Render service afterwards.`))return;if(!confirm('Final confirmation: replace the current data files with this archive?'))return;const b=e.currentTarget;b.disabled=true;b.textContent='Validating & restoring…';try{const response=await fetch('/api/admin/recovery/restore-upload',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/gzip'},body:file});const result=await response.json().catch(()=>({}));if(!response.ok||result.ok===false)throw new Error(result.error||`Restore failed (${response.status})`);alert(`Full restore completed. ${result.filesRestored} files restored.\n\nRestart the Guardian web service in Render now.\nPre-restore backup: ${result.preRestoreBackupId}`);await window.renderGuardianBackups()}catch(err){note(err.message,true)}finally{b.disabled=false;b.textContent='Upload & restore full backup'}};
   $('gbrExportConfig').onclick=()=>{location.href='/api/admin/export'};
   $('gbrImportFile').onchange=async e=>{const f=e.target.files?.[0];if(f)$('gbrImportData').value=await f.text()};
   $('gbrImportConfig').onclick=async()=>{let payload;try{payload=JSON.parse($('gbrImportData').value)}catch{return note('The configuration JSON is invalid.',true)}if(!payload?.config)return note('This is not a Guardian configuration export.',true);if(!confirm('Restore this configuration JSON? Current configuration will be replaced.'))return;try{await req('/api/admin/import',{method:'POST',body:JSON.stringify(payload)});note('Configuration restored.');}catch(e){note(e.message,true)}};
  }catch(e){c.innerHTML=`<div class="card"><h3>Backup & recovery unavailable</h3><p>${E(e.message)}</p><button onclick="renderGuardianBackups()">Retry</button></div>`}
 };

 // ============================================================
 // Developer issue tracker
 // ============================================================
 window.renderGuardianIssues=async function(){
  const c=document.getElementById('content');c.innerHTML='<div class="card"><h3>Loading developer issue tracker…</h3></div>';
  try{
   const data=await req('/api/admin/dev-issues');let issues=data.issues||[],summary=data.summary||{},selectedId=issues[0]?.id||'';let search='',filterStatus='',filterType='';
   const statusOptions=[['new','New'],['triaged','Triaged'],['in_progress','In progress'],['testing','Testing'],['ready_to_deploy','Ready to deploy'],['resolved','Resolved'],['closed','Closed']];
   const typeOptions=[['bug','Bug'],['feature','Feature request'],['task','Task'],['incident','Incident']];
   const priOptions=[['low','Low'],['normal','Normal'],['high','High'],['critical','Critical']];
   const envOptions=[['development','Development'],['staging','Staging'],['production','Production']];
   const statusLabel=v=>(statusOptions.find(x=>x[0]===v)||[v||'new',v||'New'])[1];
   const typeLabel=v=>(typeOptions.find(x=>x[0]===v)||[v||'bug',v||'Bug'])[1];
   const draw=()=>{
    const visible=issues.filter(i=>(!filterStatus||i.status===filterStatus)&&(!filterType||i.type===filterType)&&(`${i.key} ${i.title} ${i.description} ${i.area} ${i.assignedTo} ${i.createdBy}`.toLowerCase().includes(search)));
    const issue=visible.find(x=>x.id===selectedId)||visible[0]||null;selectedId=issue?.id||'';
    c.innerHTML=`<div class="gctlWrap gctlIssueWrap">
     <div class="gctlHeader"><div><div class="eyebrow">ENGINEERING WORKFLOW</div><h2>Developer Issue Tracker</h2><p>Track bugs and feature requests from triage through testing and deployment.</p></div><button id="gdiRefresh">Refresh</button></div>
     <div class="gctlStats gctlIssueStats"><div class="card"><small>ALL ISSUES</small><strong>${Number(summary.total||issues.length)}</strong><span>Recorded in Guardian</span></div><div class="card"><small>OPEN</small><strong>${Number(summary.open||0)}</strong><span>Not resolved or closed</span></div><div class="card"><small>IN TESTING</small><strong>${Number(summary.testing||0)}</strong><span>Being validated</span></div><div class="card"><small>READY TO DEPLOY</small><strong>${Number(summary.readyToDeploy||0)}</strong><span>Passed testing</span></div></div>
     <section class="card"><div class="gctlSection"><div><h3>Create an issue</h3><p>Record a reproducible bug, feature request, task or production incident. Do not paste passwords, API keys, bot tokens or session cookies.</p></div></div>
      <form id="gdiCreateForm" class="gctlIssueCreate"><label>Title<input id="gdiNewTitle" maxlength="180" required placeholder="e.g. Player list does not refresh after reconnect"></label><label>Type<select id="gdiNewType">${typeOptions.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('')}</select></label><label>Priority<select id="gdiNewPriority">${priOptions.map(x=>`<option value="${x[0]}" ${x[0]==='normal'?'selected':''}>${x[1]}</option>`).join('')}</select></label><label>Area / system<input id="gdiNewArea" placeholder="FiveM, Website, Discord bot, Database…"></label><label class="gctlFullWidth">Description<textarea id="gdiNewDescription" required rows="3" maxlength="8000" placeholder="What is wrong or what should be built? Include the impact and context."></textarea></label><div class="gctlFullWidth gctlButtons"><button>Create issue</button></div></form>
     </section>
     <div class="gctlIssueLayout"><section class="card"><div class="gctlSection"><div><h3>Issues</h3><p>${visible.length} matching records</p></div></div><div class="gctlIssueFilters"><input id="gdiSearch" value="${E(search)}" placeholder="Search key, title, area, developer…"><select id="gdiStatusFilter"><option value="">All statuses</option>${statusOptions.map(x=>`<option value="${x[0]}" ${filterStatus===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select><select id="gdiTypeFilter"><option value="">All types</option>${typeOptions.map(x=>`<option value="${x[0]}" ${filterType===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div class="gctlIssueList">${visible.map(i=>`<button type="button" class="gctlIssueListRow ${i.id===selectedId?'active':''}" data-gdi-select="${E(i.id)}"><span class="gctlIssueKey">${E(i.key)}</span><strong>${E(i.title)}</strong><span class="gctlIssueMeta">${E(typeLabel(i.type))} · ${E(statusLabel(i.status))}</span><span class="gctlIssuePills"><i class="${i.priority==='critical'?'critical':i.priority==='high'?'high':''}">${E(String(i.priority||'normal').toUpperCase())}</i><i>${E(i.assignedTo||'Unassigned')}</i></span></button>`).join('')||'<div class="emptyState">No issues match these filters. Create one above.</div>'}</div></section>
      <section class="card" id="gdiDetail">${issue?issueDetailHtml(issue):'<div class="gctlEmpty">Select an issue to view details.</div>'}</section>
     </div></div>`;
    $('gdiRefresh').onclick=()=>window.renderGuardianIssues();
    $('gdiSearch').oninput=e=>{search=e.target.value.toLowerCase();draw();const el=$('gdiSearch');el.focus();el.setSelectionRange(search.length,search.length)};
    $('gdiStatusFilter').onchange=e=>{filterStatus=e.target.value;draw()};$('gdiTypeFilter').onchange=e=>{filterType=e.target.value;draw()};
    document.querySelectorAll('[data-gdi-select]').forEach(b=>b.onclick=()=>{selectedId=b.dataset.gdiSelect;draw()});
    $('gdiCreateForm').onsubmit=async e=>{e.preventDefault();try{const r=await req('/api/admin/dev-issues',{method:'POST',body:JSON.stringify({title:$('gdiNewTitle').value.trim(),type:$('gdiNewType').value,priority:$('gdiNewPriority').value,area:$('gdiNewArea').value.trim(),description:$('gdiNewDescription').value.trim()})});note(`Created ${r.issue.key}`);selectedId=r.issue.id;await loadIssues()}catch(err){note(err.message,true)}};
    if(issue)bindIssueDetail(issue);
   };
   function issueDetailHtml(i){
    return `<div class="gctlIssueDetailHead"><div><div class="eyebrow">${E(i.key)} · Created ${E(dt(i.createdAt))}</div><h3>${E(i.title)}</h3><p>Created by ${E(i.createdBy||'Unknown')} · Updated ${E(dt(i.updatedAt))}</p></div><span class="gctlBadge ${['resolved','closed'].includes(i.status)?'good':'bad'}">${E(statusLabel(i.status))}</span></div>
     <div class="gctlIssueFields"><label>Status<select id="gdiStatus">${statusOptions.map(x=>`<option value="${x[0]}" ${i.status===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label><label>Priority<select id="gdiPriority">${priOptions.map(x=>`<option value="${x[0]}" ${i.priority===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label><label>Assigned developer<input id="gdiAssigned" value="${E(i.assignedTo||'')}" placeholder="Guardian username"></label><label>Area / system<input id="gdiArea" value="${E(i.area||'')}" placeholder="FiveM / Website / Bot"></label><label>Target version<input id="gdiVersion" value="${E(i.targetVersion||'')}" placeholder="e.g. 1.4.0"></label><label>Due date<input id="gdiDue" type="date" value="${E((i.dueDate||'').slice(0,10))}"></label><label class="gctlFullWidth">Description<textarea id="gdiDescription" rows="3">${E(i.description||'')}</textarea></label><label class="gctlFullWidth">Reproduction steps<textarea id="gdiSteps" rows="2" placeholder="Steps to reproduce">${E(i.steps||'')}</textarea></label><div class="gctlTwoCols"><label>Expected behaviour<textarea id="gdiExpected" rows="2">${E(i.expected||'')}</textarea></label><label>Actual behaviour<textarea id="gdiActual" rows="2">${E(i.actual||'')}</textarea></label></div><label class="gctlFullWidth">Resolution / implementation notes<textarea id="gdiResolution" rows="2">${E(i.resolution||'')}</textarea></label><div class="gctlFullWidth gctlButtons"><button type="button" id="gdiSaveIssue">Save issue</button></div></div>
     <div class="gctlIssueSubsection"><h4>Testing</h4><form id="gdiTestForm" class="gctlIssueFields"><label>Result<select id="gdiTestResult"><option value="passed">Passed</option><option value="failed">Failed</option><option value="blocked">Blocked</option></select></label><label>Environment<select id="gdiTestEnvironment">${envOptions.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('')}</select></label><label>Build / version<input id="gdiTestVersion" placeholder="Build or version"></label><label class="gctlFullWidth">Test notes<textarea id="gdiTestNotes" rows="2" required placeholder="What was tested and what happened?"></textarea></label><div class="gctlFullWidth"><button>Record test result</button></div></form><div class="gctlTimeline">${(i.tests||[]).map(t=>`<article><header><b class="${t.result==='passed'?'gctlSuccessText':t.result==='failed'?'gctlErrorText':''}">${E(String(t.result||'').toUpperCase())}</b> · ${E(t.environment)} · ${E(dt(t.testedAt))} · ${E(t.testedBy||'')}</header><p>${E(t.notes)}</p><small>${E(t.version||'')}</small></article>`).join('')||'<p class="muted">No test results yet.</p>'}</div></div>
     <div class="gctlIssueSubsection"><h4>Deployment history</h4><form id="gdiDeployForm" class="gctlIssueFields"><label>Environment<select id="gdiDeployEnvironment">${envOptions.map(x=>`<option value="${x[0]}" ${x[0]==='staging'?'selected':''}>${x[1]}</option>`).join('')}</select></label><label>Result<select id="gdiDeployStatus"><option value="deployed">Deployed</option><option value="failed">Failed</option><option value="rolled_back">Rolled back</option></select></label><label>Version<input id="gdiDeployVersion" placeholder="e.g. v1.2.3"></label><label>Commit / PR<input id="gdiDeployCommit" placeholder="Commit hash or PR #"></label><label class="gctlFullWidth">Deployment notes<textarea id="gdiDeployNotes" rows="2" placeholder="What changed / release notes / rollback reason"></textarea></label><div class="gctlFullWidth"><button>Record deployment</button></div></form><div class="gctlTimeline">${(i.deployments||[]).map(d=>`<article><header><b class="${d.status==='deployed'?'gctlSuccessText':d.status==='failed'?'gctlErrorText':''}">${E(String(d.status||'').replace('_',' ').toUpperCase())}</b> · ${E(d.environment)} · ${E(dt(d.createdAt))} · ${E(d.deployedBy||'')}</header><p>${E(d.notes||'')}</p><small>${E(d.version||'')} ${d.commit?'· '+E(d.commit):''}</small></article>`).join('')||'<p class="muted">No deployments recorded yet.</p>'}</div></div>
     <div class="gctlIssueSubsection"><h4>Comments & collaboration</h4><form id="gdiCommentForm" class="gctlCommentForm"><textarea id="gdiComment" rows="2" maxlength="4000" required placeholder="Add an update, question or handover note…"></textarea><button>Add comment</button></form><div class="gctlTimeline">${(i.comments||[]).slice().reverse().map(cm=>`<article><header><b>${E(cm.createdBy||'Unknown')}</b> · ${E(dt(cm.createdAt))}</header><p>${E(cm.content)}</p></article>`).join('')||'<p class="muted">No comments yet.</p>'}</div></div>
     <div class="gctlIssueSubsection"><h4>Activity history</h4><div class="gctlTimeline">${(i.events||[]).slice(0,40).map(ev=>`<article><header><b>${E(ev.actor||'SYSTEM')}</b> · ${E(ev.action||'updated')} · ${E(dt(ev.at))}</header><small>${E(JSON.stringify(ev.details||{}))}</small></article>`).join('')||'<p class="muted">No activity yet.</p>'}</div></div>`;
   }
   async function loadIssues(){const r=await req('/api/admin/dev-issues');issues=r.issues||[];summary=r.summary||{};if(!issues.some(x=>x.id===selectedId))selectedId=issues[0]?.id||'';draw()}
   function bindIssueDetail(issue){
    const detail=$('gdiDetail');detail.querySelector('#gdiSaveIssue').onclick=async()=>{try{const r=await req('/api/admin/dev-issues/'+encodeURIComponent(issue.id)+'/update',{method:'POST',body:JSON.stringify({status:detail.querySelector('#gdiStatus').value,priority:detail.querySelector('#gdiPriority').value,assignedTo:detail.querySelector('#gdiAssigned').value,area:detail.querySelector('#gdiArea').value,targetVersion:detail.querySelector('#gdiVersion').value,dueDate:detail.querySelector('#gdiDue').value,description:detail.querySelector('#gdiDescription').value,steps:detail.querySelector('#gdiSteps').value,expected:detail.querySelector('#gdiExpected').value,actual:detail.querySelector('#gdiActual').value,resolution:detail.querySelector('#gdiResolution').value})});note('Issue saved.');selectedId=r.issue.id;await loadIssues()}catch(e){note(e.message,true)}};
    detail.querySelector('#gdiTestForm').onsubmit=async e=>{e.preventDefault();try{await req('/api/admin/dev-issues/'+encodeURIComponent(issue.id)+'/tests',{method:'POST',body:JSON.stringify({result:detail.querySelector('#gdiTestResult').value,environment:detail.querySelector('#gdiTestEnvironment').value,version:detail.querySelector('#gdiTestVersion').value,notes:detail.querySelector('#gdiTestNotes').value})});note('Test result recorded.');await loadIssues()}catch(err){note(err.message,true)}};
    detail.querySelector('#gdiDeployForm').onsubmit=async e=>{e.preventDefault();try{await req('/api/admin/dev-issues/'+encodeURIComponent(issue.id)+'/deployments',{method:'POST',body:JSON.stringify({environment:detail.querySelector('#gdiDeployEnvironment').value,status:detail.querySelector('#gdiDeployStatus').value,version:detail.querySelector('#gdiDeployVersion').value,commit:detail.querySelector('#gdiDeployCommit').value,notes:detail.querySelector('#gdiDeployNotes').value})});note('Deployment record saved.');await loadIssues()}catch(err){note(err.message,true)}};
    detail.querySelector('#gdiCommentForm').onsubmit=async e=>{e.preventDefault();try{await req('/api/admin/dev-issues/'+encodeURIComponent(issue.id)+'/comments',{method:'POST',body:JSON.stringify({content:detail.querySelector('#gdiComment').value})});note('Comment added.');await loadIssues()}catch(err){note(err.message,true)}};
   }
   draw();
  }catch(e){c.innerHTML=`<div class="card"><h3>Developer issue tracker unavailable</h3><p>${E(e.message)}</p><button onclick="renderGuardianIssues()">Retry</button></div>`}
 };

})();
